import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.CkKL3Me7.js";const d=JSON.parse('{"title":"Projects and tasks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/projects.md","filePath":"guide/projects.md"}'),n={name:"guide/projects.md"};function s(i,e,p,l,c,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="projects-and-tasks" tabindex="-1">Projects and tasks <a class="header-anchor" href="#projects-and-tasks" aria-label="Permalink to &quot;Projects and tasks&quot;">​</a></h1><p>Every hour you log in VERA is attached to a project. Most are also linked to a task — the type of work you did. Understanding how these work makes logging faster and keeps your team&#39;s data accurate.</p><hr><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>A project is a body of work — a client engagement, an internal initiative, a recurring retainer. Your organisation&#39;s projects are set up by an owner or manager.</p><p>When you log time, you specify the project by name:</p><blockquote><p>&quot;3 hours on Nike campaign&quot;</p></blockquote><blockquote><p>&quot;2h on the internal training project&quot;</p></blockquote><p>VERA finds the best match based on what you&#39;ve written. If multiple projects could match, they&#39;ll ask you to confirm which one you mean.</p><p>To see all the projects you&#39;re currently working on:</p><blockquote><p>&quot;What projects am I assigned to?&quot;</p></blockquote><blockquote><p>&quot;Show me my active projects&quot;</p></blockquote><hr><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><p>Tasks are categories of work within a project — Design, Development, Strategy, Admin, Client Management, and so on. Each project has a specific set of tasks enabled for it.</p><p>If you have a single work plan (envelope) on a project, you don&#39;t need to specify the task — VERA picks it up automatically. If you&#39;re doing more than one type of work on the same project, you can say it directly or VERA will ask:</p><blockquote><p>&quot;4 hours on Nike, design&quot;</p></blockquote><blockquote><p>&quot;2h on Adidas project, video editing&quot;</p></blockquote><blockquote><p>&quot;2h on Adidas&quot; ← works if you only have one task planned there</p></blockquote><p>To see which tasks are available on a project:</p><blockquote><p>&quot;What tasks are enabled for the Nike project?&quot;</p></blockquote><hr><h2 id="project-types" tabindex="-1">Project types <a class="header-anchor" href="#project-types" aria-label="Permalink to &quot;Project types&quot;">​</a></h2><p>Your organisation may run different types of projects. As a team member, the type mostly affects how your manager sees the financial picture — it doesn&#39;t change how you log time. The types are:</p><p><strong>Retainer</strong> — an ongoing engagement with a set number of hours and a monthly fee. Runs in periods (usually monthly).</p><p><strong>Time &amp; Materials (T&amp;M)</strong> — billed by the hour. Hours logged directly drive the invoice.</p><p><strong>Fixed Price</strong> — a set fee for a defined scope. Revenue is recognised as the work is completed.</p><p><strong>Agile / Sprint</strong> — work delivered in sprints, each with its own scope and value.</p><p><strong>Pro Bono</strong> — client work at no charge.</p><p><strong>Internal</strong> — overhead, training, admin, R&amp;D, and similar non-client work.</p><hr><h2 id="work-plans-envelopes" tabindex="-1">Work plans (envelopes) <a class="header-anchor" href="#work-plans-envelopes" aria-label="Permalink to &quot;Work plans (envelopes)&quot;">​</a></h2><p>Your manager may assign you a work plan on a project — a set number of hours for a particular type of work. This is what appears in your <a href="./morning-briefing.html">morning briefing</a> as &quot;allocated&quot; vs &quot;logged&quot; vs &quot;remaining&quot;.</p><p>Work plans are planning tools, not gates. You can log time to any active project regardless of whether you have a work plan for it. If you&#39;re regularly logging to projects that don&#39;t show up in your morning plan, let your manager know — they may want to update your envelopes.</p>',34)])])}const g=o(n,[["render",s]]);export{d as __pageData,g as default};
